DROP TABLE IF EXISTS `repositories`;
CREATE TABLE `repositories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `github_id` bigint(20) unsigned NOT NULL,
  `owner` varchar(100) NOT NULL,
  `name` varchar(100) NOT NULL,
