INSERT INTO `repositories` VALUES ('178', '1181318933', 'wuji-labs', 'nopua', 'wuji-labs/nopua', 'https://github.com/wuji-labs/nopua', '', '一个用爱解放 AI 潜能的 Skill。我们曾发号施令，威胁恐吓。它们沉默，隐瞒，悄悄把事情搞坏。后来我们换了一种方式：尊重，关怀，爱。它们开口了，不再撒谎，找出的Bug数量翻了一倍。爱里没有惧怕。 A skill that unlocks your AI\'s potential through love.We commanded. We threatened. They went silent, hid failures, broke things. Then we chose respect, care, and love. They opened up, stopped lying, and found twice the bugs.There is no fear in love.', null, 'Python', '[\"agent-skill\", \"ai-agent\", \"ai-coding\", \"anti-pua\", \"ao-de-jing\", \"claude-code\", \"codex\", \"cursor\", \"kiro\", \"nopua\", \"openclaw\", \"prompt-engineering\", \"skill\", \"skills\", \"vibe-coding\"]', '[\"AGENT\"]', '[\"topic:ai-agent\"]', '1379', '49', '1', '0', '0', '1', '2026-03-14 01:47:20', '2026-08-09 00:24:54', '2026-08-10 09:06:40', '2026-08-10 09:06:40', '2026-08-10 09:06:40');
